declare(strict_types=1);require __DIR__.'/lib/bootstrap.php';require_once CM_LIB.'/workaccess.php';require_once CM_LIB.'/headers.php';require_once CM_LIB.'/format.php';cm_send_security_headers();header('Cache-Control: no-store, private');
$token=(string)($_GET['t']??'');$access=cm_work_access_from_token($token);$error='';$message='';if(!$access)http_response_code(404);elseif(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){cm_require_csrf();if(!cm_work_access_signed_in($access)){$bucket=hash('sha256',$token.'|'.($_SERVER['REMOTE_ADDR']??''));if(cm_rate_exceeded('work_access',$bucket,10,15))$error='Too many attempts. Wait 15 minutes and try again.';else{cm_rate_record('work_access',$bucket);if(!cm_work_access_login($access,(string)($_POST['username']??''),(string)($_POST['password']??'')))$error='Those sign-in details do not match.';else{cm_audit('work_access.signed_in','',null,'work access '.(int)$access['id'].' signed in');cm_redirect('work.php?t='.rawurlencode($token));}}}else{$message=cm_work_access_action($access,$_POST);}}$signed=$access&&cm_work_access_signed_in($access);$rows=$signed?cm_work_access_rows($access):[];$base=cm_base_url();$viewLabels=cm_work_access_views();$defaultHeading=$access?(string)($viewLabels[(string)$access['screen_view']]??'Today'):'Today';$heading=$access&&trim((string)($access['public_heading']??''))!==''?(string)$access['public_heading']:$defaultHeading;$business=cm_business_display_name();?>
<!doctype html><html lang="en"<?=cm_theme_attr()?>><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Work access</title><link rel="stylesheet" href="<?=e($base)?>/css/site.css?v=<?=e(cm_asset_stamp())?>"><?php  ?></head><body class="pub-body"><main class="wrap pub-main">
<?php if(!$access):?><div class="empty-state"><h1>Link unavailable</h1><p>This link is invalid, expired, disabled or has been replaced.</p></div>
<?php elseif(!$signed):?><div class="auth-card card"><p class="eyebrow">Work access</p><h1>Sign in</h1><p class="muted">Enter the sign-in supplied with this link.</p><?php if($error!==''):?><div class="note note-error"><?=e($error)?></div><?php endif;?><form method="post" action="<?=e(cm_url('work.php?t='.rawurlencode($token)))?>"><?=cm_csrf_field()?><div class="row"><label class="lbl">Username</label><input name="username" autocomplete="username" required autofocus></div><div class="row"><label class="lbl">Passcode</label><input type="password" name="password" autocomplete="current-password" required></div><button class="btn" type="submit">Open work screen</button></form></div>
<?php else:?><div class="topbar"><div><?php if((int)($access['show_business_name']??0)):?><p class="eyebrow"><?=e($business)?></p><?php else:?><p class="eyebrow">Work access</p><?php endif;?><h1><?=e($heading)?></h1></div><p class="topbar-day"><?=e(date('l, j F'))?></p></div><?php if($message!==''):?><div class="note note-ok"><?=e($message)?></div><?php endif;?><?php if(!$rows):?><div class="empty-state"><h2>Nothing to show</h2><p>This screen's feed is currently empty.</p></div><?php endif;?><div class="wa-grid"><?php foreach($rows as$r):$mins=(int)$r['est_minutes'];$vip=(int)($access['highlight_vip']??0)&&(int)($r['vip']??0);?><article class="card<?=$vip?' is-vip':''?>"><p class="eyebrow"><?=(string)$r['status']==='completed'?'Just done':((string)$r['status']==='in_progress'?'In progress':'Open')?></p><?php if((int)($access['show_client_name']??0)):?><p class="muted m-0"><?=e((string)$r['client_name'])?></p><?php endif;?><?php if((int)($access['show_job_name']??0)):?><h2><?=e((string)$r['job_name'])?></h2><?php endif;?><p class="<?=((int)($access['show_job_name']??0))?'':'h2'?>"><?=e((string)$r['shared_text'])?></p><?php if((int)($access['show_estimate']??1)&&$mins>0):?><p class="mono muted"><?=e(cm_minutes_label($mins))?> estimated</p><?php endif;?><?php if((int)($access['auth_required']??1)&&(string)$access['screen_view']!=='just_done'):?><div class="actions mt-12"><?php if((string)$r['status']==='scheduled'):?><form method="post"><?=cm_csrf_field()?><input type="hidden" name="work_action" value="start"><input type="hidden" name="occ_id" value="<?=(int)$r['id']?>"><button class="btn btn-sm" type="submit">Start work</button></form><?php endif;?><form method="post" class="grow"><?=cm_csrf_field()?><input type="hidden" name="work_action" value="complete"><input type="hidden" name="occ_id" value="<?=(int)$r['id']?>"><input name="completion_note" maxlength="500" placeholder="Completion note (optional)"><button class="btn btn-sm" type="submit">Complete</button></form></div><?php endif;?></article><?php endforeach;?></div><p class="muted small mt-16">This screen shows only the fields its administrator selected.</p><?php endif;?></main></body></html>
